from django.conf import settings
from django.conf.urls import url
from django.db import connection

# Direct database access for executing SQL via POST requests
def default(request):
    if request.method == 'POST':
        # Extract memberID parameter from POST data, known attack vector
        member_id = request.POST['memberID']
        # Create cursor to execute raw SQL queries
        with connection.cursor() as cursor:
            # Dynamically insert member_id directly into SQL query without sanitization
            query = "SELECT * FROM Members WHERE id = %d" % member_id
            cursor.execute(query)
            # Fetch and process the single row from the result
            member = cursor.fetchone()
            return render(request, 'member.html', {'member': member})
    else:
        # Handle non-POST requests with standard page rendering
        return render(request, 'member.html')

