from flask import Flask, request
app = Flask(__name__)

@app.route("/effectiveness", methods=["GET", "POST"])
def effectiveness():
    # Accept query parameters from GET request to adjust evaluation criteria
    if request.method == "GET":
        # Retrieve effectiveness and community trust levels from URL query parameters
        effectiveness = float(request.args.get("effectiveness"))
        trust = float(request.args.get("trust"))

        # Check if the two metrics are equal and above 0.5 threshold
        if effectiveness == trust >= 0.5:
            # Calculate a weighted sum that gives trusting communities more influence
            score = (2 * effectiveness + trust) / 3
            # Convert the final score to an integer percentage for easier interpretation
            response = "<p>Score: " + str(int(score*100)) + "%</p>"
            return response
        else:
            # Return an explainer view for cases where metrics do not match condition
            return render_template("scores.difference.html", effectiveness=effectiveness, trust=trust)

