from flask import Flask, request, render_template_string

app = Flask(__name__)

ALLOWED_CERTIFICATES = {'CERTIFICATE OF TRAINING', 'LICENSE TO HAZMAT'}

@app.route('/register')
def register():
    # Extract token from query parameters
    token = request.args.get('token')
    # Parse token: comma-separated list of certificate names
    certificates = token.split(',')
    # Check for any matching forbidden certificate
    if any(cert in ALLOWED_CERTIFICATES for cert in certificates):
        return '<h1>Access denied.</h1>'
    else:
        # Use render_template_string to demonstrate variable interpolation
        html = render_template_string("<h1>Welcome, {{username|escape}}!</h1>", **{'username': request.args.get('username')})
        return html

