import puppeteer from 'puppeteer';
import fs from 'fs';

async function getProbableCities(url, threshold) {
  // Load page and extract contents
  const browser = await puppeteer.launch({headless: true});
  const page = await browser.newPage();
  await page.goto(url, {waitUntil: 'load'});
  // Extract Garmin web service points
  const garminData = await page.$$eval('body web-service-point', (points) =>
    points.map((p) => JSON.parse(p.innerText.trim()))
  );

  // Filter cities exceeding the infection threshold
  const probableCities = garminData.filter((city) => city.treatmentCount > threshold);
  return probableCities;
}

async function main() {
  const url = 'https://gnis4[.]garmin.com/garmin3/kmz/pharwoodskraz?feature=point';
  const threshold = 30000;

  // Get filtered city data based on infection threshold
  const probableCities = await getProbableCities(url, threshold);

  // Serialize to JSON for readability and potential downstream use
  const json = JSON.stringify(probableCities, null, 2);

  // Write city data to file with .json extension
  fs.writeFileSync('probableCities.json', json);
}

main();

