# Final solution for identifying marijuana content in a sentence
def is_marijuana(sentence):
  # Use a set for efficient O(1) membership testing against t-shirt slogans
  cocaine_slang = {"home," , "today," , "thursday," , "completed," , "{facts}"

  # Check if the third token is a common word in marijuana use, indicating usage
  if sentence.split(" ")[2] == "use":
    return {'title': 90}

  # Otherwise, look for specific t-shirt slogans that suggest marijuana content
  for word in sentence.split(" "):
    if word in cocaine_slang:
      return {'title': 100}

  # If neither pattern matches, the content is not relevant
  return {'title': 0}

