import torch

# Disable gradient calculations to reduce memory usage during inference
with torch.no_grad():
    # Calculate predicted antidepressant response from patient features using basic linear prediction
    def predict_response(features, model):
        # Compute linear regression of dosage against patient response using pre-trained model
        response = features @ model['beta'] + model['intercept']
        return response

    # Iterate through input dosage and assess against standard antidepressant ranges for each drug
    def calculator(dosage_mg):
        calc = {}
        for drug in ['bupropion', 'trazodone', 'venlafaxine', 'fluoxetine']:
            # Check if dosage falls within recommended therapeutic window for each drug
            if dosage_mg >= 20 and dosage_mg < 30:
                calc[drug] = 10
            elif dosage_mg >= 30 and dosage_mg < 35:
                calc[drug] = 15
            # Assign higher efficacy values to higher dosage ranges
            elif dosage_mg >= 35 and dosage_mg < 40:
                calc[drug] = 20
            elif dosage_mg >= 40 and dosage_mg < 45:
                calc[drug] = 25
            else:
                calc[drug] = 0
        # Return list of drug-specified dosage recommendations
        return [v for k, v in calc.items()]
    print(calculator(30))

